-- Unlinked JV · tax vouchers — read-only SQL pack (Cure MCP). Riyadh needs the EXSYS. prefix when run alone; branch ALL works unqualified.
-- Screens: VOUCHTAX = GL_VOUCHER_TAX_MASTER/DETAILS -> VOUCHER_MASTERS/DETAILS ; CMVCHTAX = CM_VOUCHER_TAX_MASTER/DETAILS -> CM_VOUCHER_MASTER/DETAILS.
-- NOTE: GL_TRANSACTIONS_DETAILS.VOUCHER_TAX_NO is a function lookup from the tax master, so use the base tables.
-- 1) Journal-tax transactions with tax-line and JV totals (pack 18 per row; Riyadh > 3,600 rows -> run twice with WHERE RN <= 3600 / RN > 3600)
SELECT 'G'||LPAD(FLOOR((RN-1)/18),3,'0') B, LISTAGG(S,'~') WITHIN GROUP (ORDER BY RN) X FROM (SELECT ROW_NUMBER() OVER (ORDER BY t.VOUCHER_TAX_NO) RN, t.VOUCHER_TAX_NO||'|'||t.VOUCHER_NO||'|'||t.STATUS||'|'||TO_CHAR(t.VM_DATE,'YYYY-MM-DD')||'|'||(SELECT ROUND(SUM(DR_AMOUNT),2)||'/'||ROUND(SUM(VAT_AMT),2)||'/'||COUNT(*) FROM GL_VOUCHER_TAX_DETAILS d WHERE d.VOUCHER_TAX_NO=t.VOUCHER_TAX_NO)||'|'||vm.STATUS||'|'||(SELECT ROUND(SUM(DR_AMOUNT),2)||'/'||ROUND(SUM(CASE WHEN ACCOUNT_NO='1263000' THEN DR_AMOUNT-CR_AMOUNT END),2)||'/'||COUNT(*) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=t.VOUCHER_NO)||'|'||t.ENTRY_USER||'|'||REPLACE(REPLACE(REPLACE(SUBSTR(t.DESCRIPTION,1,60),CHR(10),' '),'|','/'),'~','-') S FROM GL_VOUCHER_TAX_MASTER t LEFT JOIN VOUCHER_MASTERS vm ON vm.VOUCHER_NO=t.VOUCHER_NO) GROUP BY FLOOR((RN-1)/18) ORDER BY 1;
-- 2) Cash-tax transactions with tax-line and cash-voucher totals
SELECT 'C'||LPAD(FLOOR((RN-1)/15),3,'0') B, LISTAGG(S,'~') WITHIN GROUP (ORDER BY RN) X FROM (SELECT ROW_NUMBER() OVER (ORDER BY t.CM_VOCHTAX_NO) RN, t.CM_VOCHTAX_NO||'|'||t.CM_VOUCHER_NO||'|'||t.STATUS||'|'||TO_CHAR(t.CM_VM_DATE,'YYYY-MM-DD')||'|'||(SELECT ROUND(SUM(DR_AMOUNT-CR_AMOUNT),2)||'/'||ROUND(SUM(VAT_AMT),2)||'/'||COUNT(*) FROM CM_VOUCHER_TAX_DETAILS d WHERE d.CM_VOCHTAX_NO=t.CM_VOCHTAX_NO)||'/'||t.TOTAL_AMOUNT||'/'||t.CM_ACC_CODE||'|'||cm.STATUS||'|'||(SELECT ROUND(SUM(CASE WHEN NVL(CM_ACC_FLAG,'N')<>'Y' THEN DR_AMOUNT-CR_AMOUNT END),2)||'/'||ROUND(SUM(CASE WHEN ACCOUNT_NO='1263000' THEN DR_AMOUNT-CR_AMOUNT END),2)||'/'||COUNT(*) FROM CM_VOUCHER_DETAILS d WHERE d.CM_VOUCHER_NO=t.CM_VOUCHER_NO)||'/'||cm.TOTAL_AMOUNT||'/'||cm.CM_ACC_CODE||'|'||t.ENTRY_USER||'|'||REPLACE(REPLACE(REPLACE(SUBSTR(NVL(t.DESCRIPTION,t.NARRATIVE),1,60),CHR(10),' '),'|','/'),'~','-') S FROM CM_VOUCHER_TAX_MASTER t LEFT JOIN CM_VOUCHER_MASTER cm ON cm.CM_VOUCHER_NO=t.CM_VOUCHER_NO) GROUP BY FLOOR((RN-1)/15) ORDER BY 1;
-- 3) Live system-type JVs (VM_TYPE 'S', GL) that no journal-tax transaction points to
SELECT vm.VOUCHER_NO V, vm.STATUS S, TO_CHAR(vm.VM_DATE,'YYYY-MM-DD') D, NVL(vm.SUB_SYSTEM_CODE,'-') SS, vm.VM_TYPE T, vm.JV_CM_SEQUENCE SQ, vm.JV_CM_SEQUENCE_OLD SQO, (SELECT ROUND(SUM(DR_AMOUNT),2) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=vm.VOUCHER_NO) DR, (SELECT ROUND(SUM(DR_AMOUNT-CR_AMOUNT),2) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=vm.VOUCHER_NO AND d.ACCOUNT_NO='1263000') VAT, vm.ENTRY_USER EU, SUBSTR(vm.DESCRIPTION,1,90) DS FROM VOUCHER_MASTERS vm WHERE vm.VM_TYPE='S' AND NVL(vm.SUB_SYSTEM_CODE,'GL')='GL' AND vm.STATUS<>'C' AND NOT EXISTS (SELECT 1 FROM GL_VOUCHER_TAX_MASTER t WHERE t.VOUCHER_NO=vm.VOUCHER_NO) ORDER BY vm.VM_DATE;
-- 4) Twins of linked JVs (same date + debit total, unlinked, live) -> then compare line fingerprints (query 5)
SELECT a.V LV, a.T TNO, b.V TWIN, b.S TS, b.TY, TO_CHAR(a.D,'YYYY-MM-DD') D, a.DR, a.N, b.N BN, SUBSTR(b.DS,1,70) BDS FROM (SELECT t.VOUCHER_TAX_NO T, vm.VOUCHER_NO V, vm.VM_DATE D, (SELECT ROUND(SUM(DR_AMOUNT),2) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=vm.VOUCHER_NO) DR, (SELECT COUNT(*) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=vm.VOUCHER_NO) N FROM GL_VOUCHER_TAX_MASTER t JOIN VOUCHER_MASTERS vm ON vm.VOUCHER_NO=t.VOUCHER_NO WHERE vm.STATUS<>'C') a JOIN (SELECT vm.VOUCHER_NO V, vm.STATUS S, vm.VM_TYPE TY, vm.VM_DATE D, vm.DESCRIPTION DS, (SELECT ROUND(SUM(DR_AMOUNT),2) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=vm.VOUCHER_NO) DR, (SELECT COUNT(*) FROM VOUCHER_DETAILS d WHERE d.VOUCHER_NO=vm.VOUCHER_NO) N FROM VOUCHER_MASTERS vm WHERE vm.STATUS<>'C' AND NOT EXISTS (SELECT 1 FROM GL_VOUCHER_TAX_MASTER t WHERE t.VOUCHER_NO=vm.VOUCHER_NO)) b ON b.D=a.D AND b.DR=a.DR AND b.DR>0 ORDER BY a.D;
-- 5) Line fingerprint for the vouchers returned by 4 (fill the IN list)
SELECT VOUCHER_NO V, LISTAGG(ACCOUNT_NO||':'||NVL(SUB_ACCOUNT_NO,'-')||':'||DR_AMOUNT||':'||CR_AMOUNT, ',') WITHIN GROUP (ORDER BY ACCOUNT_NO, NVL(SUB_ACCOUNT_NO,'-'), DR_AMOUNT, CR_AMOUNT) FP FROM VOUCHER_DETAILS WHERE VOUCHER_NO IN ('{V1}','{V2}') GROUP BY VOUCHER_NO;
-- 6) Live cash vouchers matching a cancelled/open cash-tax transaction (date, cash account, amount)
SELECT t.CM_VOCHTAX_NO TNO, t.STATUS TS, TO_CHAR(t.CM_VM_DATE,'YYYY-MM-DD') D, t.TOTAL_AMOUNT TAMT, TO_CHAR(t.CM_ACC_CODE) ACC, b.CM_VOUCHER_NO V, b.STATUS VS, b.TOTAL_AMOUNT VAMT, b.ENTRY_USER EU, SUBSTR(b.NARRATIVE,1,60) DS FROM CM_VOUCHER_TAX_MASTER t JOIN CM_VOUCHER_MASTER b ON b.CM_VM_DATE=t.CM_VM_DATE AND b.TOTAL_AMOUNT=t.TOTAL_AMOUNT AND NVL(TO_CHAR(b.CM_ACC_CODE),'-')=NVL(TO_CHAR(t.CM_ACC_CODE),'-') AND b.STATUS<>'C' AND NOT EXISTS (SELECT 1 FROM CM_VOUCHER_TAX_MASTER t2 WHERE t2.CM_VOUCHER_NO=b.CM_VOUCHER_NO) WHERE t.STATUS<>'P' ORDER BY 3;
-- 7) Same supplier invoice (INVOICE_NO + TAX_NO) in more than one posted tax transaction
SELECT SRC, INV, TAXNO, COUNT(*) NT, LISTAGG(T||'>'||V||'>'||D||'>'||DR||'>'||VAT, ',') WITHIN GROUP (ORDER BY D) TXS, SUM(VAT) VAT FROM (SELECT 'GL' SRC, d.INVOICE_NO INV, d.TAX_NO TAXNO, d.VOUCHER_TAX_NO T, m.VOUCHER_NO V, TO_CHAR(m.VM_DATE,'YYYY-MM-DD') D, ROUND(SUM(d.DR_AMOUNT),2) DR, ROUND(SUM(d.VAT_AMT),2) VAT FROM GL_VOUCHER_TAX_DETAILS d JOIN GL_VOUCHER_TAX_MASTER m ON m.VOUCHER_TAX_NO=d.VOUCHER_TAX_NO WHERE m.STATUS='P' AND d.INVOICE_NO IS NOT NULL AND NVL(d.VAT_AMT,0)<>0 GROUP BY d.INVOICE_NO, d.TAX_NO, d.VOUCHER_TAX_NO, m.VOUCHER_NO, m.VM_DATE UNION ALL SELECT 'CM', d.INVOICE_NO, d.TAX_NO, d.CM_VOCHTAX_NO, m.CM_VOUCHER_NO, TO_CHAR(m.CM_VM_DATE,'YYYY-MM-DD'), ROUND(SUM(d.DR_AMOUNT),2), ROUND(SUM(d.VAT_AMT),2) FROM CM_VOUCHER_TAX_DETAILS d JOIN CM_VOUCHER_TAX_MASTER m ON m.CM_VOCHTAX_NO=d.CM_VOCHTAX_NO WHERE m.STATUS='P' AND d.INVOICE_NO IS NOT NULL AND NVL(d.VAT_AMT,0)<>0 GROUP BY d.INVOICE_NO, d.TAX_NO, d.CM_VOCHTAX_NO, m.CM_VOUCHER_NO, m.CM_VM_DATE) GROUP BY SRC, INV, TAXNO HAVING COUNT(*)>1 ORDER BY 1,2;
